import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Main {
    record Task(String name, LocalDate dueDate) { }
    public static void main(String[] args) {
        List<Task> tasks = new ArrayList<>(List.of(
            new Task("Submit report", LocalDate.of(2026, 10, 20)),
            new Task("Review notes", LocalDate.of(2026, 10, 14))));
        tasks.sort(Comparator.comparing(Task::dueDate).thenComparing(Task::name));
        tasks.forEach(t -> System.out.println(t.dueDate() + " " + t.name()));
    }
}
